import{_ as r,h as n,i as a,c as i,v as t,p as T,x as o,m as d,e as p,S as s}from"./chunks/framework.Dvtg8yj2.js";const A=JSON.parse('{"title":"追踪：TTFT 分位","description":"","frontmatter":{"title":"追踪：TTFT 分位","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ttft-percentiles.md","filePath":"llm/ttft-percentiles.md","lastUpdated":1788454257000}'),c={name:"llm/ttft-percentiles.md"};function h(m,e,f,P,E,u){const l=n("Mermaid");return a(),i("div",null,[e[1]||(e[1]=t('<h1 id="追踪-ttft-分位" tabindex="-1">追踪：TTFT 分位 <a class="header-anchor" href="#追踪-ttft-分位" aria-label="Permalink to &quot;追踪：TTFT 分位&quot;">​</a></h1><div class="epigraph"><p>平均数告诉你典型用户还行；分位曲线才告诉你谁被长提示、缓存未命中和队头阻塞留在了门口。追踪要把这根曲线按桶切开，而不是只往仪表盘扔一个 P99。</p><footer>—— 对照生成服务把 TTFT 作为请求级跨度，用直方图与足够样本估计尾部</footer></div><p><a href="/llm/ttft">TTFT</a> 专文定义墙钟从请求接受到首个被接受的输出 token；<a href="/llm/serving-metrics">服务指标</a> 把它与 TPOT、吞吐并列；<a href="/llm/serving-slo">SLO</a> 把分位数写成合同。本篇只写<strong>怎么追踪</strong>：时间戳打在哪、直方图怎么切、标签基数如何控制、样本不够时 P99 在撒谎。没有追踪，SLO 是一张不会响的纸；追踪口径错了，告警会冤枉调度器或放过真正的排队。不编造一篇 TTFT percentile tracing 的会议论文。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>TTFT 是多个阶段之和：网关排队、鉴权与 <a href="/llm/serving-tokenizer-cost">encode</a>、可能的同步安全卡点、调度等待、前填、第一次采样。只在引擎 kernel 入口打点，会把队列藏掉，看板永远「模型很快、用户很慢」。只在负载均衡器打点，又会把 TLS、客户端慢发完整提示算进去。测点必须与用户可见超时、与 SLO 文本一致：通常是「网关收齐完整提示」到「第一个输出 token 进入返回流」。心跳、空 SSE 注释、工具状态事件不是 token。</p><p>第二个问题是聚合。全局 P99 把 128 token 闲聊与 32k 文档问答揉在一起，优化会去修已经很快的那一群。缓存命中与未命中是双峰：混合分位由未命中峰决定，平均被命中流量粉饰。追踪若不按长度桶、命中、模型、是否分块前填分列，P99 就不能指导动作。</p><h3 id="分位是顺序统计量-不是另一个平均值" tabindex="-1">分位是顺序统计量，不是另一个平均值 <a class="header-anchor" href="#分位是顺序统计量-不是另一个平均值" aria-label="Permalink to &quot;分位是顺序统计量，不是另一个平均值&quot;">​</a></h3><p>窗口内 \\(N\\) 个 TTFT 样本的经验 \\(p\\) 分位，大约是第 \\(\\lceil p(N-1)\\rceil\\) 个顺序统计量。\\(N=200\\) 时「P99」几乎是最倒霉的一两条，明天换一批请求数字就能跳一倍。P99.9 更甚。没有足够完成量就不要把三九写进告警；改用 P95 加长窗口，或改报超阈值比例。最大值当 SLO 更糟：它随观测时间单调变坏，激励停止测量。</p><p><span class="marginnote">预热阶段的 CUDA 编译、第一次加载适配器、JIT 图捕获，会写成当天最肥的尾巴。稳态分位应丢掉发布后的一段冷启动，或把「冷」标成单独的请求类，避免冤枉连续批。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每条请求一条根跨度 <code>llm.ttft</code>，属性至少：模型、精度、适配器版本、提示 token 数（encode 后）、输出是否流式、前缀缓存命中长度、队列深度快照。子跨度按预算拆：<code>queue</code>、<code>moderate</code>、<code>prefill</code>、<code>sample_first</code>。TTFT 的结束事件与流式协议的第一个合法 token 对齐，见服务指标专文对「被接受的输出 token」的定义。</p><p>存储用直方图而非每次都算全量百分位。桶边界应按对数或按产品长度档（例如 0–512、512–2k、2k–8k、8k+ 的 TTFT 毫秒桶），因为延迟跨三到四个数量级。OpenTelemetry 一类导出时，<strong>不要</strong>把 <code>prompt_tokens</code> 当高基数标签逐值贴上，否则时间序列爆炸；应先分桶再贴 <code>prompt_bucket=2k-8k</code>。用户 ID、会话 ID 只进采样追踪，不进指标标签。</p><p>告警看两级。窗口级：某类请求的 \\(q_{0.99}\\) 或超阈值比例持续越线，驱动减批、拒长、限流。请求级：单条 TTFT 超线记入 <a href="/llm/goodput">goodput</a> 的不合格，用于容量曲线，而不是每条都呼叫。重试去重：同一用户可见尝试只进一次分位，三次内部重试进三次会把尾巴写歪。</p><h3 id="切片比单个-p99-更有用" tabindex="-1">切片比单个 P99 更有用 <a class="header-anchor" href="#切片比单个-p99-更有用" aria-label="Permalink to &quot;切片比单个 P99 更有用&quot;">​</a></h3><p>最小切片集：长度桶 × 缓存命中/未命中 × 模型。可选再加：是否 <a href="/llm/chunked-prefill">chunked prefill</a>、是否同步审核、区域。报表先看未命中长提示的 P95/P99，那是前填与排队的真值；再看命中短提示的 P50，那是路径下限。若短提示 P50 也涨，问题在控制面或同步卡点，不在注意力核。</p><p>压测与线上共用同一套跨度名。压测要扫并发，画出 P50/P95/P99 TTFT 对 QPS 的三条曲线，拐点是 <a href="/llm/serving-slo">SLO</a> 工作点。只报空载 92 ms 没有追踪价值。</p>',16)),(a(),T(s,null,{default:o(()=>[p(l,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20LR%0A%20%20ARR%5B%22%E6%94%B6%E9%BD%90%E6%8F%90%E7%A4%BA%22%5D%20--%3E%20Q%5B%22queue%22%5D%0A%20%20Q%20--%3E%20M%5B%22%E5%8F%AF%E9%80%89%E5%90%8C%E6%AD%A5%E5%AE%A1%E6%A0%B8%22%5D%0A%20%20M%20--%3E%20P%5B%22prefill%22%5D%0A%20%20P%20--%3E%20S%5B%22%E9%A6%96%20token%22%5D%0A%20%20S%20--%3E%20H%5B%22%E7%9B%B4%E6%96%B9%E5%9B%BE%20%C2%B7%20%E6%8C%89%E9%95%BF%E5%BA%A6%E4%B8%8E%E5%91%BD%E4%B8%AD%E5%88%87%E7%89%87%22%5D%0A%20%20H%20--%3E%20AL%5B%22%E7%AA%97%E5%8F%A3%E5%88%86%E4%BD%8D%E5%91%8A%E8%AD%A6%22%5D%0A%20%20H%20--%3E%20GP%5B%22%E8%AF%B7%E6%B1%82%E7%BA%A7%20goodput%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>尾部从哪来，追踪就该能指到哪一段子跨度。<code>queue</code> 主导：调度与 KV 不足，动作是准入与优先级。<code>prefill</code> 主导：提示长度或未切片的原子前填，动作是分块、拆 PD、拒超长。<code>moderate</code> 主导：同步分类器或规则，动作是异步化、缩小审核模型、或接受这笔 TTFT 税，见 <a href="/llm/moderation-inline">内容安全同步卡点</a>。子跨度缺失时，所有优化都变成猜。</p><h3 id="子跨度把尾巴指到动作" tabindex="-1">子跨度把尾巴指到动作 <a class="header-anchor" href="#子跨度把尾巴指到动作" aria-label="Permalink to &quot;子跨度把尾巴指到动作&quot;">​</a></h3><p>时钟：多机必须 NTP/PTP，跨度用同一时间源。回拨会制造负 TTFT，应丢弃或钳零并计数异常。流式在代理缓冲里攒包，服务端已发出首 token，用户仍未看见——产品 SLO 若承诺「屏幕出字」，测点要放到边缘或接受服务端 TTFT 与体感的差，并在文档写清。</p><p><span class="marginnote">百分位对样本数敏感。经验上，稳定地谈 P99 需要窗口内至少数千完成事件；谈 P99.9 再高一个数量级。流量小的模型不要签三九，改签 P95 或「超 2s 的比例」。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>追踪自己有成本。每 token 打跨度会把追踪后端打满；TTFT 只关心到首 token，decode 逐步 ITL 应另用摘要直方图，不要为每个 ITL 开跨度。高基数标签是比延迟本身更常见的事故。合规上，跨度属性不要带提示原文。</p><p>多区域聚合：全局 P99 会被高延迟区拖住。应先分区再看全局，故障转移是否把用户打到冷区，会在 TTFT 分位上立刻出现双峰，见 <a href="/llm/multi-region-failover">多区域故障转移</a>。思维链隐藏时，用户可见 TTFT 可能是「最终答案第一个字」，内部已经跑完一段长前填——两个测点都要，只报一个会与产品文案冲突。</p><p><span class="marginnote">不要用日志 grep 的 P99 替代指标直方图。日志采样 1%、指标全量，两条曲线会对不上。合同统计走指标；日志用来下钻那条超线的子跨度。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TTFT 追踪的测点须与 SLO 一致：收齐提示到第一个被接受的输出 token，不含心跳。</li><li>用直方图与长度/命中/模型切片；禁止把无界 token 数当指标标签。</li><li>分位需要足够样本；冷启动与内部重试要单独处理，否则尾巴是假的。</li><li>子跨度区分排队、审核、前填，才能把告警映射到动作。</li><li>窗口分位驱动降级，请求级违约驱动 goodput；两者都要。</li><li>出处：对照 OpenTelemetry 直方图实践与生成服务对 TTFT/TBT 分位数的测量惯例；定义见站内 TTFT 与 SLO 专文。</li></ul>',11))])}const _=r(c,[["render",h]]);export{A as __pageData,_ as default};
